from typing import List

def max_sub_square_under_k(matrix: List[List[int]], k: int) -> int:
    n = len(matrix)
    pre = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n):
        for j in range(n):
            pre[i + 1][j + 1] = matrix[i][j] + pre[i][j + 1] + pre[i + 1][j] - pre[i][j]

    ans = 0
    for L in range(1, n + 1):
        # every L x L window must stay within k (sample treats sum == k as OK)
        if all(pre[i + L][j + L] - pre[i][j + L] - pre[i + L][j] + pre[i][j] <= k
               for i in range(n - L + 1) for j in range(n - L + 1)):
            ans = L
    return ans
